const SL=t=>[...document.querySelectorAll(".slide")].find(s=>s.dataset.t===t);
const RMO=matchMedia("(prefers-reduced-motion: reduce)").matches;
function tween(dur,fn,done){let raf=0;const t0=performance.now(),e=t=>1-Math.pow(1-t,3);const fr=t=>{const k=clamp((t-t0)/dur,0,1);fn(e(k),k);if(k<1)raf=requestAnimationFrame(fr);else if(done)done()};raf=requestAnimationFrame(fr);return()=>cancelAnimationFrame(raf)}
document.querySelectorAll(".slide").forEach(s=>{if(s.querySelector("[data-fx-type]"))FXR.add(s,fxTypography(s,{delay:220,gap:120}))});

