function pathSeg(el,opt){opt=opt||{};el.classList.add("path-seg");PK.forEach(k=>{const p=PATHS[k];const b=H("button",{class:`tg num ${k}`,title:`Caminho ${p.tag} · ${p.n}`},el,p.tag);b.addEventListener("click",e=>{e.stopPropagation();setPath(k,el)})});const nm=opt.name===false?null:H("span",{class:"pname"},el,"");onPath(k=>{el.querySelectorAll(".tg").forEach(b=>b.classList.toggle("on",b.classList.contains(k)));if(nm){const p=PATHS[k];nm.innerHTML=`<b style="color:${p.col}">${p.n}</b> · ${p.T}`}})}

/* ---------- before / after slider ---------- */
function baSlider(root,o){root.classList.add("ba");root.innerHTML="";const B=H("div",{class:"ba-b"},root),A=H("div",{class:"ba-a"},root);
const la=H("span",{class:"ba-lbl a"},root,o.la||"Antes"),lb=H("span",{class:"ba-lbl b"},root,o.lb||"Depois");H("div",{class:"ba-h"},root);const k=H("button",{class:"ba-k","aria-label":"divisor"},root,"‹ ›");
let x=50,drag=null,stopT=null;const set=v=>{x=clamp(v,0,100);root.style.setProperty("--x",x.toFixed(2)+"%");la.classList.toggle("hid",x<16);lb.classList.toggle("hid",x>84);if(o.onSet)o.onSet(x)};
const from=e=>{const r=root.getBoundingClientRect();return(e.clientX-r.left)/r.width*100};
const halt=()=>{if(stopT){stopT();stopT=null}};
const glide=(to,dur,done)=>{halt();const f=x;stopT=tween(RMO?0:dur,e=>set(f+(to-f)*e),()=>{stopT=null;if(done)done()})};
const down=e=>{if(e.pointerType==="mouse"&&e.button!==0)return;if(o.knobOnly&&e.target!==k)return;halt();drag={id:e.pointerId,x0:e.clientX,m:0};try{root.setPointerCapture(e.pointerId)}catch(_){}root.classList.add("drag");if(!o.knobOnly)set(from(e));e.preventDefault();e.stopPropagation()};
root.addEventListener("pointerdown",down);root.addEventListener("pointermove",e=>{if(!drag||e.pointerId!==drag.id)return;drag.m=Math.max(drag.m,Math.abs(e.clientX-drag.x0));set(from(e))});
const up=e=>{if(!drag||(e&&e.pointerId!=null&&e.pointerId!==drag.id))return;try{root.releasePointerCapture(drag.id)}catch(_){}drag=null;root.classList.remove("drag")};root.addEventListener("pointerup",up);root.addEventListener("pointercancel",up);addEventListener("pointerup",up);
root.addEventListener("click",e=>e.stopPropagation());
k.addEventListener("keydown",e=>{if(e.key==="ArrowLeft"||e.key==="ArrowRight"){e.preventDefault();e.stopPropagation();halt();set(x+(e.key==="ArrowRight"?2:-2))}});
const api={A,B,set,glide,halt,get x(){return x},play(){halt();set(100);glide(50,1000)},onSet:null};o.onSet=v=>{if(api.onSet)api.onSet(v)};set(100);return api}
function baCtl(el,ba,o){el.innerHTML="";const an=H("button",{class:"btn"},el,"▶ Animar comparação");let run=false;const stopA=()=>{run=false;an.classList.remove("on");an.textContent="▶ Animar comparação";ba.halt()};
an.addEventListener("click",e=>{e.stopPropagation();if(run){stopA();return}run=true;an.classList.add("on");an.textContent="■ Parar";ba.glide(100,700,()=>ba.glide(0,1500,()=>ba.glide(50,900,stopA)))});
H("span",{style:"font:500 10px 'JetBrains Mono',monospace;letter-spacing:.14em;text-transform:uppercase;color:#8A97A8;margin:0 2px 0 8px"},el,"Posição");
[[100,o.a||"Antes"],[50,"50 / 50"],[0,o.b||"Depois"]].forEach(([v,l])=>{const b=H("button",{class:"tg","data-pos":v},el,l);b.addEventListener("click",e=>{e.stopPropagation();stopA();ba.glide(v,600)})});
H("span",{class:"hnt"},el,o.hint||"Arraste o divisor · clique no painel · ← →");ba.onSet=v=>el.querySelectorAll("[data-pos]").forEach(b=>b.classList.toggle("on",Math.abs(+b.dataset.pos-v)<1.5));ba.onSet(ba.x);return{stop:stopA}}

